INSERT INTO activities (id, club_id, created_by, type, title, description, content_json, xp_reward) VALUES (1, 1, 1, 'puzzle-hint', 'Mates en 1 (con pistas)', 'Aprende a dar jaque mate', '{"puzzles": [{"fen": "6k1/5ppp/8/8/8/8/5PPP/R5K1 w - - 0 1", "moves": ["a1a8"], "prompt": "Mate en 1: ¡la fila de atrás!"}, {"fen": "7k/R7/8/8/8/8/8/1R4K1 w - - 0 1", "moves": ["b1b8"], "prompt": "Mate en 1 con las dos torres"}, {"fen": "7k/8/6K1/8/8/8/8/Q7 w - - 0 1", "moves": ["a1a8"], "prompt": "Mate en 1 con la dama"}, {"fen": "4r1k1/5ppp/8/8/8/8/5PPP/6K1 b - - 0 1", "moves": ["e8e1"], "prompt": "Ahora juegas con negras: mate en 1"}, {"fen": "r3k3/8/8/3N4/8/8/8/4K3 w - - 0 1", "moves": ["d5c7", "e8d7", "c7a8"], "prompt": "¡Ataque doble del caballo!"}]}', 30);
INSERT INTO activities (id, club_id, created_by, type, title, description, content_json, xp_reward) VALUES (2, 1, 1, 'puzzle-blitz', 'Reto relámpago: mates', '¡Rápido!', '{"puzzles": [{"fen": "6k1/5ppp/8/8/8/8/5PPP/3R2K1 w - - 0 1", "moves": ["d1d8"], "prompt": "Mate en 1"}, {"fen": "k7/8/1K6/8/8/8/8/7Q w - - 0 1", "moves": ["h1h8"], "prompt": "Mate en 1"}, {"fen": "3k4/8/3K4/8/8/8/8/R7 w - - 0 1", "moves": ["a1a8"], "prompt": "Mate en 1"}, {"fen": "6k1/5p1p/6pB/8/8/8/5PPP/3Q2K1 w - - 0 1", "moves": ["d1d8"], "prompt": "Mate en 1"}, {"fen": "r1bqkbnr/pppp1ppp/2n5/4p3/2B1P3/5Q2/PPPP1PPP/RNB1K1NR w KQkq - 0 1", "moves": ["f3f7"], "prompt": "¡El mate del pastor!"}], "timeLimitSec": 30}', 30);
INSERT INTO activities (id, club_id, created_by, type, title, description, content_json, xp_reward) VALUES (3, 1, 1, 'pgn-lesson', 'La trampa del pastor', 'Lección interactiva', '{"pgn": "[Event \"Mate del pastor\"]\n[FEN \"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1\"]\n\n{ Vamos a ver una trampa muy famosa. ¡Atento! }\n1. e4 e5 2. Bc4 { El alfil apunta a f7, la casilla más débil. [%cal Gc4f7] } 2... Nc6\n3. Qh5 { [%ask ¿Qué debe jugar el negro para no perder? Defiende f7 y el peón de e5] } 3... g6\n( 3... Qe7 { [%pts 60] ¡Bien! También defiende f7. } )\n( 3... Nf6 { ¡Cuidado! Ahora la dama da mate en f7. } )\n{ ¡Eso es! El peón echa a la dama. [%csl Gg6] } 4. Qf3 { La dama vuelve a atacar f7. [%cal Gf3f7] [%ask ¡Tapa el ataque desarrollando una pieza!] } 4... Nf6 { ¡Perfecto! El caballo tapa la diagonal y se desarrolla. }\n( 4... Qf6 { [%pts 50] Defiende, pero la dama sale muy pronto. } ) *"}', 40);
INSERT INTO activities (id, club_id, created_by, type, title, description, content_json, xp_reward) VALUES (4, 1, 1, 'fruit-collector', 'Frutas por el tablero', 'Mueve las piezas con cabeza', '{"levels": [{"piece": "R", "start": "a1", "fruits": ["a5", "e5", "e8"], "rocks": []}, {"piece": "N", "start": "b1", "fruits": ["c3", "e4", "d6"], "rocks": []}, {"piece": "B", "start": "c1", "fruits": ["f4", "h6", "e7"], "rocks": ["d2"]}, {"piece": "Q", "start": "d1", "fruits": ["a4", "h5", "d8", "b8"], "rocks": ["d4", "e4"]}]}', 25);
