INSERT INTO activities (club_id, created_by, type, title, description, content_json, xp_reward) VALUES (1, 1, 'puzzle-hint', 'Ejercicios de la Lección 10: Clavadas y Rayos X', 'Resuelve estos 8 problemas sacados de la Lección 10 del PDF', '{"puzzles":[{"fen":"4k3/8/8/4q3/8/8/5B2/1K1R4 w - - 0 1","moves":["d1e1"],"prompt":"Juegan blancas: Clava a la dama negra al rey"},{"fen":"1r2r1k1/pp3pp1/2pq1n1p/3p4/3P3B/1QP4P/PP3PP1/3RR1K1 w - - 0 1","moves":["h4g3"],"prompt":"Juegan blancas: Haz un ataque de Rayos X (Skewer) a la dama y la torre"},{"fen":"1r3k2/5ppp/8/8/3Q4/6q1/PPP5/1K3R2 w - - 0 1","moves":["f1g1"],"prompt":"Juegan blancas: Rayos X a lo largo de la columna G"},{"fen":"r1b1k2r/1pp2ppp/p1p2n2/2b5/4q3/5N2/PPPP1PPP/RNBQ1RK1 w kq - 0 1","moves":["f1e1"],"prompt":"Juegan blancas: Clava a la dama"},{"fen":"2r2rk1/4qppp/p2Q4/1p2p1P1/4P2P/5P1R/PPP5/1K1R4 b - - 0 1","moves":["f8d8","c8d8"],"prompt":"Juegan negras: Rayos X a la dama y torre blancas"},{"fen":"6qk/6p1/p1p2p1p/PpB5/1P6/8/4K2Q/8 b - - 0 1","moves":["g8a2"],"prompt":"Juegan negras: Haz un Rayos X con jaque"},{"fen":"4r1k1/p4p1p/6p1/5q2/7P/P1pQ4/1P3PP1/1K1R4 b - - 0 1","moves":["e8d8"],"prompt":"Juegan negras: Clavada y Rayos X combinados"},{"fen":"1r3k2/4qppp/Q2p4/5b2/8/b1pB4/PP3PPP/1KR4R b - - 0 1","moves":["e7e2"],"prompt":"Juegan negras: Aprovecha la clavada doble sobre el alfil de d3"}]}', 40);
INSERT INTO activities (club_id, created_by, type, title, description, content_json, xp_reward) VALUES (1, 1, 'puzzle-hint', 'Ejercicios de la Lecci�n 11: Ataques Descubiertos', 'Resuelve estos 8 problemas sacados de la Lecci�n 11 del PDF', '{"puzzles":[{"fen":"8/k7/8/3RN2q/8/8/6K1/8 w - - 0 1","moves":["e5c6"],"prompt":"Juegan blancas: Ataque descubierto a la dama"},{"fen":"3r1rk1/p4p1p/N1p1q1bp/1p1pQ3/3P4/2P2P1P/PP3P2/3RR1K1 b - - 0 1","moves":["e6c8"],"prompt":"Juegan negras: Ataque descubierto a la dama"},{"fen":"4q1k1/5ppp/8/8/4N3/8/PPP5/1K2R3 w - - 0 1","moves":["e4f6"],"prompt":"Juegan blancas: Ataque descubierto con jaque"},{"fen":"8/p1p1R3/pkP4p/3P2p1/5p2/1P1KN2P/2P2r2/4r3 w - - 0 1","moves":["e3c4"],"prompt":"Juegan blancas: Ataque descubierto a la torre"},{"fen":"2k5/8/1R6/1N6/8/8/6K1/1q6 w - - 0 1","moves":["b5a7","b5d6"],"prompt":"Juegan blancas: Jaque doble"},{"fen":"7k/5pr1/p5rp/Pp1q4/1P1B4/2P5/3Q1PPP/6K1 w - - 0 1","moves":["d4g7"],"prompt":"Juegan blancas: Ataque descubierto a la dama"},{"fen":"5q2/1R1P3k/6p1/8/5P2/6P1/P6P/6K1 w - - 0 1","moves":["d7d8Q","d7d8q"],"prompt":"Juegan blancas: Promoci�n con ataque descubierto"},{"fen":"1r1q1r2/pb1b1pkp/1p1np1p1/8/1P1N4/4P3/P1B2PPP/1B1R1RK1 w - - 0 1","moves":["d4f5"],"prompt":"Juegan blancas: Jaque doble"}]}', 40);
